//! Page structs for agents. Display values are computed here from loaded rows; no
//! database access (.offrails/structure.md). Generated by `cargo offrails generate resource agents name:string description:text`.

use askama::Template;

use super::Ctx;
use crate::models::{Errors, agent};
use crate::routes::paths;

/// One agent as pages show it: every value a display string.
/// APP: times are shown in UTC; convert to the reader's zone here when the app knows it.
#[derive(Debug, Clone)]
pub struct AgentView {
    pub id: i64,
    pub label: String,
    pub name: String,
    pub description: String,
}

impl AgentView {
    pub fn from_model(r: &agent::Model) -> Self {
        Self {
            id: r.id,
            label: r.label(),
            name: r.name.clone(),
            description: r.description.clone(),
        }
    }
}

/// `GET /agents`
#[derive(Template)]
#[template(path = "agents/index.html")]
pub struct AgentsIndex {
    pub ctx: Ctx,
    pub agents: Vec<AgentView>,
    pub page: u64,
    pub more: bool,
}

impl AgentsIndex {
    /// The pagination component's page count: this one, and the next when the query found more
    /// (no COUNT query).
    pub fn pages(&self) -> u64 {
        self.page + u64::from(self.more)
    }

    /// Where its links go (`{base}page=n`).
    pub fn page_base(&self) -> String {
        format!("{}?", paths::agents())
    }
}

/// `GET /agents/{id}`
#[derive(Template)]
#[template(path = "agents/show.html")]
pub struct AgentsShow {
    pub ctx: Ctx,
    pub agent: AgentView,
}

/// `GET /agents/new`, and a failed create (422).
#[derive(Template)]
#[template(path = "agents/new.html")]
pub struct AgentsNew {
    pub ctx: Ctx,
    pub params: agent::AgentParams,
    pub errors: Errors,
    pub action: String,
}

/// `GET /agents/{id}/edit`, and a failed update (422).
#[derive(Template)]
#[template(path = "agents/edit.html")]
pub struct AgentsEdit {
    pub ctx: Ctx,
    pub id: i64,
    pub params: agent::AgentParams,
    pub errors: Errors,
    pub action: String,
}
